    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Initialize a graph with n nodes and edges
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        // Initialize a boolean array to keep track of visited nodes
        boolean[] visited = new boolean[n];

        // Initialize the minimum time required to collect all apples and return to node 0
        int minTime = 0;

        // Perform a depth-first search starting from node 0
        dfs(graph, visited, hasApple, 0, minTime);

        return minTime;
    }

    private void dfs(List<List<Integer>> graph, boolean[] visited, boolean[] hasApple, int node, int minTime) {
        // If the current node has not been visited before, mark it as visited and update the minimum time
        if (!visited[node]) {
            visited[node] = true;
            minTime++;
        }

        // If the current node has an apple, update the minimum time
        if (hasApple[node]) {
            minTime++;
        }

        // Recursively visit all the neighbors of the current node
        for (int neighbor : graph.get(node)) {
            if (!visited[neighbor]) {
                dfs(graph, visited, hasApple, neighbor, minTime);
            }
        }
    }
}
